<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Throwable; use Pterodactyl\Models\User; use Pterodactyl\Models\Backup; use Pterodactyl\Models\Server; use Pterodactyl\Models\Permission; use Pterodactyl\Repositories\Wings\DaemonServerRepository; class Snapshot { public static function server(Server $server, User $user): array { $server->loadMissing(['egg', 'node', 'allocations']); return [ 'id' => (string) (config('pterodactyl.features.new_server_identifiers') ? $server->identifier : $server->uuidShort), 'uuid' => $server->uuid, 'name' => $server->name, 'description' => (string) $server->description, 'node' => (string) $server->node?->name, 'node_id' => (int) $server->node_id, 'owner' => $server->owner_id === $user->id, 'status' => $server->status, 'suspended' => $server->isSuspended(), 'installing' => !$server->isInstalled(), 'transferring' => $server->transfer !== null, 'limits' => ['memory' => (int) $server->memory, 'disk' => (int) $server->disk, 'cpu' => (int) $server->cpu], 'backup_limit' => (int) $server->backup_limit, 'egg' => ['uuid' => (string) $server->egg?->uuid, 'name' => (string) $server->egg?->name], 'allocations' => $server->allocations->map(fn ($allocation) => [ 'id' => (int) $allocation->id, 'ip' => (string) $allocation->ip, 'ip_alias' => (string) $allocation->ip_alias, 'port' => (int) $allocation->port, 'notes' => (string) $allocation->notes, 'is_default' => (int) $allocation->id === (int) $server->allocation_id, ])->values()->all(), 'sftp' => ['ip' => (string) $server->node?->fqdn, 'port' => (int) ($server->node?->daemonSFTP ?? 2022)], ]; } public static function live(Server $server, array $shape): array { try { $details = app(DaemonServerRepository::class)->setServer($server)->getDetails(); } catch (Throwable) { return ['state' => $shape['suspended'] ? 'suspended' : 'unknown', 'error' => 'The node could not be reached.', 'usage' => null]; } $stats = (array) ($details['utilization'] ?? []); $state = (string) ($details['state'] ?? $stats['state'] ?? 'offline'); if ($shape['suspended']) { $state = 'suspended'; } elseif ($shape['transferring']) { $state = 'transferring'; } elseif (in_array($shape['status'], ['installing', 'install_failed', 'reinstall_failed', 'restoring_backup'], true)) { $state = (string) $shape['status']; } return [ 'state' => array_key_exists($state, Format::STATES) ? $state : 'offline', 'error' => null, 'usage' => [ 'memory' => (int) ($stats['memory_bytes'] ?? 0), 'cpu' => (float) ($stats['cpu_absolute'] ?? 0), 'disk' => (int) ($stats['disk_bytes'] ?? 0), 'rx' => (int) ($stats['network']['rx_bytes'] ?? 0), 'tx' => (int) ($stats['network']['tx_bytes'] ?? 0), 'uptime' => (int) ($stats['uptime'] ?? 0), ], ]; } public static function console(Server $server, User $user, int $lines): array { if (!$user->can(Permission::ACTION_WEBSOCKET_CONNECT, $server)) { return [null, 'This account cannot read the console on this server.']; } $tail = app(ConsoleLog::class)->tail($server, $lines); return $tail === null ? [null, 'The node did not hand back the console.'] : [$tail, null]; } public static function backups(Server $server, User $user): ?array { if (!$user->can(Permission::ACTION_BACKUP_READ, $server)) { return null; } return $server->backups() ->orderByDesc('created_at') ->limit(25) ->get() ->map(fn (Backup $backup) => [ 'uuid' => $backup->uuid, 'name' => $backup->name, 'is_locked' => (bool) $backup->is_locked, 'is_successful' => (bool) $backup->is_successful, 'bytes' => (int) $backup->bytes, 'checksum' => $backup->checksum, 'ignored_files' => implode("\n", (array) $backup->ignored_files), 'created_at' => $backup->created_at?->toAtomString(), 'completed_at' => $backup->completed_at?->toAtomString(), ]) ->all(); } } 